package parser_test

import (
	"log/slog"
	"strings"
	"testing"

	"github.com/acityonmars/martian-robots/internal/engine"
	"github.com/acityonmars/martian-robots/internal/parser"
)

var discardLogger *slog.Logger = slog.New(slog.DiscardHandler)

func Test_ParseInputData_Builds_World_And_Plans_From_Valid_Input(t *testing.T) {
	input := []string{
		"5 3",
		"1 1 E",
		"RFRFRFRF",
		"3 2 N",
		"FRRFLLFFRRFLL",
	}

	world, robotPlans, err := parser.ParseInputData(input, discardLogger)
	if err != nil {
		t.Fatalf("ParseInputData() error = %v", err)
	}

	t.Run("world uses the given upper-right corner", func(t *testing.T) {
		if !world.HasPosition(engine.Position{X: 5, Y: 3}) {
			t.Error("upper-right corner 5 3 is off the grid, want on the grid")
		}
		if world.HasPosition(engine.Position{X: 6, Y: 3}) {
			t.Error("6 3 is on the grid, want off the grid")
		}
	})

	t.Run("one plan per robot, in input order", func(t *testing.T) {
		if got, want := len(robotPlans), 2; got != want {
			t.Fatalf("plans = %d, want %d", got, want)
		}
		cases := []struct {
			robot    string
			commands int
		}{
			{"1 1 E", 8},
			{"3 2 N", 13},
		}
		for i, want := range cases {
			plan := robotPlans[i]
			if got := plan.Robot.String(); got != want.robot {
				t.Errorf("plan %d robot = %q, want %q", i, got, want.robot)
			}
			if got := len(plan.Commands); got != want.commands {
				t.Errorf("plan %d commands = %d, want %d", i, got, want.commands)
			}
			if plan.World != world {
				t.Errorf("plan %d does not share the parsed world", i)
			}
		}
	})
}

func Test_ParseInputData_Accepts_Maximum_Coordinate(t *testing.T) {
	input := []string{"50 50", "50 50 N", "L"}

	if _, _, err := parser.ParseInputData(input, discardLogger); err != nil {
		t.Errorf("ParseInputData() error = %v, want nil for coordinate 50", err)
	}
}

func Test_ParseInputData_Rejects_Invalid_Input(t *testing.T) {
	cases := []struct {
		name  string
		input []string
	}{
		{"too few lines", []string{"5 3", "1 1 E"}},
		{"robot without commands", []string{"5 3", "1 1 E", "F", "2 2 N"}},
		{"world with one number", []string{"5", "1 1 E", "F"}},
		{"world not a number", []string{"5 x", "1 1 E", "F"}},
		{"world above max coordinate", []string{"51 3", "1 1 E", "F"}},
		{"robot with two fields", []string{"5 3", "1 1", "F"}},
		{"robot x not a number", []string{"5 3", "x 1 E", "F"}},
		{"unknown orientation", []string{"5 3", "1 1 X", "F"}},
		{"lowercase orientation", []string{"5 3", "1 1 e", "F"}},
		{"unknown command", []string{"5 3", "1 1 E", "FXF"}},
		{"lowercase command", []string{"5 3", "1 1 E", "f"}},
		{"commands too long", []string{"5 3", "1 1 E", strings.Repeat("F", 101)}},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			if _, _, err := parser.ParseInputData(tc.input, discardLogger); err == nil {
				t.Errorf("ParseInputData(%q) error = nil, want error", tc.input)
			}
		})
	}
}

// Spec: "The maximum value for any coordinate is 50", and a robot starts on the grid.
func Test_ParseInputData_Rejects_Robot_Starting_Outside_Grid(t *testing.T) {
	cases := []struct {
		name  string
		robot string
	}{
		{"x beyond upper-right", "6 1 E"}, // world has (x:5, y:3) so the x coord is beyond the world!
		{"y beyond upper-right", "1 4 E"}, // world has (x:5, y:3) so the y coord is beyond the world!
		{"negative x", "-1 0 N"},
		{"negative y", "0 -1 N"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			input := []string{"5 3", tc.robot, "F"}
			if _, _, err := parser.ParseInputData(input, discardLogger); err == nil {
				t.Errorf("robot %q on a 5 3 grid: error = nil, want error (robot must start on the grid)", tc.robot)
			}
		})
	}
}

// The lower-left corner is fixed at 0 0, so a negative upper-right gives a grid with no cells.
func Test_ParseInputData_Rejects_Negative_World_Coordinate(t *testing.T) {
	for _, world := range []string{"-1 3", "5 -1"} {
		t.Run(world, func(t *testing.T) {
			input := []string{world, "0 0 N", "F"}
			if _, _, err := parser.ParseInputData(input, discardLogger); err == nil {
				t.Errorf("world %q: error = nil, want error (coordinates must be 0..50)", world)
			}
		})
	}
}

// Spec: "All instruction strings will be less than 100 characters in length."
func Test_ParseInputData_Limits_Instructions_To_Less_Than_100_Characters(t *testing.T) {
	t.Run("99 characters accepted", func(t *testing.T) {
		input := []string{"5 3", "1 1 N", strings.Repeat("L", 99)}
		if _, _, err := parser.ParseInputData(input, discardLogger); err != nil {
			t.Errorf("99 instructions: error = %v, want nil", err)
		}
	})

	t.Run("100 characters rejected", func(t *testing.T) {
		input := []string{"5 3", "1 1 N", strings.Repeat("L", 100)}
		if _, _, err := parser.ParseInputData(input, discardLogger); err == nil {
			t.Error("100 instructions: error = nil, want error (spec requires < 100)")
		}
	})
}
